create table if not exists public.business_earned_perks (id uuid primary key default gen_random_uuid(), business_id uuid not null, perk_code text not null, status text not null default 'earned' check(status in ('earned','active','redeemed','expired')), source text not null default 'progression', earned_at timestamptz not null default now(), expires_at timestamptz, metadata jsonb not null default '{}'::jsonb, unique(business_id,perk_code,status));
create table if not exists public.business_progression_events (id uuid primary key default gen_random_uuid(), business_id uuid not null, user_id uuid references auth.users(id) on delete set null, event_code text not null, points integer not null default 0, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.business_geofences (id uuid primary key default gen_random_uuid(), business_id uuid not null, location_id uuid references public.locations(id) on delete cascade, radius_meters integer not null default 150 check(radius_meters between 25 and 5000), notification_enabled boolean not null default false, notification_payload jsonb not null default '{}'::jsonb, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.business_search_boosts (id uuid primary key default gen_random_uuid(), business_id uuid not null, location_id uuid references public.locations(id) on delete cascade, boost_weight numeric not null default 1.0, source_perk_id uuid references public.business_earned_perks(id) on delete set null, active boolean not null default true, starts_at timestamptz not null default now(), ends_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.qr_redemptions (id uuid primary key default gen_random_uuid(), qr_code_id uuid not null references public.qr_codes(id) on delete cascade, user_id uuid references auth.users(id) on delete set null, redeemed_at timestamptz not null default now(), unique(qr_code_id,user_id));
alter table public.qr_codes add column if not exists single_use boolean not null default false;
alter table public.qr_codes add column if not exists max_redemptions integer;
create or replace function public.consume_single_use_qr(p_code text, p_user_id uuid default auth.uid()) returns jsonb language plpgsql security invoker as $$ declare q public.qr_codes%rowtype; r integer; begin select * into q from public.qr_codes where code=p_code and active=true for update; if not found then raise exception 'QR code not found or inactive'; end if; if q.single_use then insert into public.qr_redemptions(qr_code_id,user_id) values(q.id,p_user_id) on conflict do nothing; get diagnostics r=row_count; if r=0 then raise exception 'QR code already used by this user'; end if; if q.max_redemptions is not null and (select count(*) from public.qr_redemptions where qr_code_id=q.id)>=q.max_redemptions then update public.qr_codes set active=false where id=q.id; raise exception 'QR code redemption limit reached'; end if; end if; return jsonb_build_object('ok',true,'qr_code_id',q.id,'single_use',q.single_use); end; $$;
create or replace function public.admin_authorization_v1(p_user_id uuid default auth.uid()) returns jsonb language sql stable security invoker as $$ select jsonb_build_object('authorized',coalesce(p.is_admin,false) or p.role::text='admin','role',p.role::text,'is_admin',p.is_admin) from public.profiles p where p.id=p_user_id; $$;
create or replace function public.award_business_progression_perk(p_business_id uuid,p_perk_code text,p_user_id uuid default auth.uid()) returns jsonb language plpgsql security invoker as $$ declare tier text; ok boolean; begin select b.business_tier into tier from public.businesses b join public.business_members bm on bm.business_id=b.id where b.id=p_business_id and bm.user_id=p_user_id and lower(bm.role) in ('owner','admin','manager'); if tier is null then raise exception 'Business management authorization required'; end if; ok:=lower(tier) in ('growth','enterprise','fleet'); if not ok then raise exception 'Perk requires Growth or above'; end if; insert into public.business_earned_perks(business_id,perk_code) values(p_business_id,p_perk_code) on conflict do nothing; insert into public.business_progression_events(business_id,user_id,event_code,points,metadata) values(p_business_id,p_user_id,'perk_earned',100,jsonb_build_object('perk',p_perk_code)); return jsonb_build_object('ok',true,'business_id',p_business_id,'perk_code',p_perk_code,'tier',tier); end; $$;
create index if not exists idx_business_perks_business on public.business_earned_perks(business_id,status);
create index if not exists idx_business_geofences_location on public.business_geofences(location_id,active);
create index if not exists idx_business_boosts_location on public.business_search_boosts(location_id,active);
